// Pseudo-config snippet for per-tenant CKNE policy
const policy = {
  tenants: {
    t1: { ckne: 0.2, maxParallelism: 4, checkpointMs: 5000 },
    t2: { ckne: 0.8, maxParallelism: 16, checkpointMs: 1000 }
  }
}
```

